from collections import Mapping
def deep_merge_nodes(nodes):
    result = Mapping()
    stack = [result]

    for node in nodes:
        current_dict = stack[-1]
        for key, value in node.items():
            while key in current_dict:
                if isinstance(current_dict[key], Mapping) and isinstance(value, Mapping):
                    # Merge nested dictionaries iteratively
                    if not isinstance(current_dict[key], Mapping):
                        current_dict[key] = Mapping()
                    stack.append(current_dict[key])
                    current_dict = stack[-1]
                current_dict[key] = value
            stack.pop()

    return result

from argparse import ArgumentParser
def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_arguments = list(unparsed_arguments)

    def try_subparser(subparser_name):
        try:
            args, remaining = subparsers[subparser_name].parse_known_args(remaining_arguments)
            if args:
                parsed_args[subparser_name] = args
            return remaining
        except SystemExit:
            return remaining_arguments

    while remaining_arguments:
        for subparser_name, subparser in subparsers.items():
            remaining_arguments = try_subparser(subparser_name)
            if not remaining_arguments:
                break

    return parsed_args, remaining_arguments

