        if id(item) in seen:
            return
        seen.add(id(item))

        if isinstance(item, (tuple, list)):
            for arg in item:
                normalize(arg)
                if not isinstance(arg, str) and not hasattr(arg, 'implements') and not hasattr(arg, 'declare'):
