def parse_args(self, args):
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg.split('--control-')[1]] = args[arg]
        elif arg.startswith('--nested-'):
            nested_args[arg.split('--nested-')[1]] = args[arg]
        else:
            if arg not in nested_args and arg not in control_args:
                nested_args[arg] = args[arg]

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    if extra_vars is not None and not all(isinstance(var, dict) for var in extra_vars):
        raise ValueError("extra_vars must be a list of dictionaries")

    if extra_vars is None:
        return vars_dict

    merged_dict = vars_dict.copy()  # Create a copy to avoid mutating the input

    for var in extra_vars:
        merged_dict.update(var)  # Directly update the copy without overwriting existing keys

    return merged_dict

import subprocess
def run_command(cmd):
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode!= 0:
        raise Exception(f'Command failed with return code {res.returncode}: {res.stderr}')
    return res.stdout
def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    if verbose is None:
        verbose = os.getenv('ANSIBLE_VERBOSITY', 'vv')
    if extra_vars is None:
        extra_vars = {}
    if ansible_args is None:
        ansible_args = {}

    cmd = ['ansible-playbook', playbook_path]
    cmd.extend(['--extra-vars', f'{k}={v}' for k, v in extra_vars.items()])
    cmd.append('--vv' + verbose)
    cmd.extend([
        f'--inventory {ir_workspace.path}',
        f'--limit {ir_plugin.target_group_names}',
    ])
    cmd.extend([f'--{k} {v}' for k, v in ansible_args.items()])

    output = run_command(cmd)
    return output

